// Get structured outputs from previous nodes
const resume = $node["Resume Extractor"].json;
const job = $node["Job Extractor"].json;

// Safe defaults
const resumeSkills = (resume.skills || []).map(s => s.toLowerCase());
const jobSkills = (job.required_skills || []).map(s => s.toLowerCase());

const resumeExperience = resume.years_experience || 0;
const jobExperience = job.minimum_experience || 0;

const resumeEducation = (resume.education_level || "").toLowerCase();
const jobEducation = (job.preferred_education || "").toLowerCase();

// -----------------------------
// 1️⃣ Skill Matching (50% weight)
// -----------------------------
let matchedSkills = jobSkills.filter(skill => resumeSkills.includes(skill));
let missingSkills = jobSkills.filter(skill => !resumeSkills.includes(skill));

let skillScore = jobSkills.length > 0
  ? (matchedSkills.length / jobSkills.length) * 50
  : 0;

// -----------------------------
// 2️⃣ Experience Matching (30% weight)
// -----------------------------
let experienceScore = 0;

if (resumeExperience >= jobExperience) {
  experienceScore = 30;
} else {
  experienceScore = (resumeExperience / jobExperience) * 30;
}

// -----------------------------
// 3️⃣ Education Matching (20% weight)
// -----------------------------
let educationScore = 0;

if (resumeEducation && jobEducation && resumeEducation.includes(jobEducation)) {
  educationScore = 20;
}

// -----------------------------
// Final Score
// -----------------------------
let totalScore = skillScore + experienceScore + educationScore;

// Bias-safe output (no name, no gender, no college prestige)
return [
  {
    overall_score: Math.round(totalScore),
    breakdown: {
      skill_score: Math.round(skillScore),
      experience_score: Math.round(experienceScore),
      education_score: Math.round(educationScore)
    },
    matched_skills: matchedSkills,
    missing_skills: missingSkills,
    experience_gap: Math.max(0, jobExperience - resumeExperience)
  }
];
